const tests = $('Code in JavaScript').all();
const results = $input.all();
const norm = s => (s || "").toLowerCase().replace(/[\s\-‐‑–]/g, "");

let hit1 = 0, hit3 = 0;
const rows = tests.map((t, i) => {
  const chunks = results.slice(i * 3, i * 3 + 3).map(r => r.json.document.pageContent);
  const ans = norm(t.json.answer);
  const rank = chunks.findIndex(c => norm(c).includes(ans)) + 1;
  if (rank === 1) hit1++;
  if (rank >= 1) hit3++;
  return { json: { id: t.json.id, question: t.json.question, answer: t.json.answer, rank: rank || "miss" } };
});

const n = tests.length;
rows.push({ json: { id: "TOTAL", question: `Hit@1: ${hit1}/${n} = ${Math.round(hit1 / n * 100)}% | Hit@3: ${hit3}/${n} = ${Math.round(hit3 / n * 100)}%` } });

return rows;
